function normalizeRefund(order,input,actor,inst,t){if(!effectiveToggle(inst,t,'F-092'))throw Object.assign(new Error('Refund management is not enabled for this store.'),{status:403});const amount=Number(input?.amount),amountCents=Math.round(amount*100),totalCents=Math.round(Number(order.total||0)*100),already=(order.refunds||[]).reduce((sum,row)=>sum+Math.round(Number(row.amount||0)*100),0),reason=String(input?.reason||'').trim();if(!Number.isFinite(amount)||amountCents<1)throw Object.assign(new Error('Refund amount must be at least 0.01.'),{status:400});if(!reason||reason.length>500)throw Object.assign(new Error('Enter a refund reason up to 500 characters.'),{status:400});if(!['paid','partially_refunded'].includes(order.paymentStatus))throw Object.assign(new Error('Only paid orders can be refunded.'),{status:409});if(already+amountCents>totalCents)throw Object.assign(new Error('Refund amount cannot exceed the remaining paid order balance.'),{status:409});const refunds=[...(order.refunds||[]),{id:crypto.randomUUID(),amount:amountCents/100,baseAmount:Math.round((amountCents/Math.max(0.00000001,Number(order.exchangeRate)||1)))/100,reason,method:'manual-record',by:actor,at:new Date().toISOString()}],refunded=refunds.reduce((sum,row)=>sum+Math.round(Number(row.amount||0)*100),0);return {refunds,paymentStatus:refunded>=totalCents?'refunded':'partially_refunded'}}
