function auditHash(value){return crypto.createHash('sha256').update(JSON.stringify(value)).digest('hex')}
function ensureAuditCheckpoint(){control.audit||=[];if(!control.auditCheckpoint){const legacy=control.audit.filter(row=>!row.hash);control.auditCheckpoint=auditHash({version:1,legacy});persist()}if(!control.auditHeadHash){const head=control.audit.find(row=>row.hash);if(head){control.auditHeadHash=head.hash;persist()}}}
