function verifyAuditChain(state){const rows=state.audit||[];let expected=null,verified=0,valid=true,reason='';if(state.auditHeadHash&&rows.find(row=>row.hash)?.hash!==state.auditHeadHash){valid=false;reason='Audit log head is missing or does not match its checkpoint.'}for(let i=0;valid&&i<rows.length;i++){const row=rows[i];if(!row.hash){const legacy=rows.filter(x=>!x.hash);if(auditHash({version:1,legacy})!==state.auditCheckpoint){valid=false;reason='Legacy audit checkpoint mismatch.'}else if(expected&&expected!==state.auditCheckpoint){valid=false;reason='Signed audit chain does not reach the legacy checkpoint.'}break}if(expected&&row.hash!==expected){valid=false;reason='Audit entries were removed, reordered, or replaced.';break}const data={...row};delete data.hash;if(auditHash(data)!==row.hash){valid=false;reason='Audit entry hash mismatch.';break}expected=row.previousHash;verified++}if(valid&&expected&&expected!==state.auditCheckpoint){valid=false;reason='Signed audit chain does not reach the legacy checkpoint.'}return {valid,verified,legacyCheckpoint:state.auditCheckpoint,legacyEntries:rows.filter(x=>!x.hash).length,reason:reason||'Audit hash chain is valid.'}}

