function webhookPublicAddress(value){if(net.isIP(value)!==4)return false;const p=value.split('.').map(Number),n=((p[0]<<24)|(p[1]<<16)|(p[2]<<8)|p[3])>>>0;const blocked=[[0x00000000,8],[0x0a000000,8],[0x64400000,10],[0x7f000000,8],[0xa9fe0000,16],[0xac100000,12],[0xc0000000,24],[0xc0000200,24],[0xc0a80000,16],[0xc6120000,15],[0xc6336400,24],[0xcb007100,24],[0xe0000000,4]];return !blocked.some(([base,bits])=>{const mask=bits===0?0:(0xffffffff<<(32-bits))>>>0;return (n&mask)===(base&mask)})}
