async function runWebhookSweep(){for(const inst of control.instances.filter(x=>x.status==='active'&&!x.deletedAt)){try{const t=readTenant(inst),due=(t.webhookDeliveries||[]).filter(x=>x.status==='pending'&&(x.nextAttemptAt<=Date.now()||x.leaseUntil&&x.leaseUntil<Date.now())).slice(0,10);for(const item of due){const hook=(t.webhooks||[]).find(row=>row.id===item.webhookId&&row.active),enabled=hook&&effectiveToggle(inst,t,['slack','discord'].includes(hook.platform)?'F-165':hook.platform==='automation'?'F-167':'F-161');if(!enabled){item.status='cancelled';item.lastError='Webhook feature is disabled or destination is unavailable.';writeTenant(inst,t);continue}item.leaseUntil=0;processWebhookDelivery(inst,item.id).catch(()=>{})}}catch{}}}
